using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

namespace McpHttpServer;

[McpServerResource(UriTemplate = "config://app/settings",
    Name = "AppSettings",
    Description = "Returns the current application configuration data")]
public static class ConfigResource
{
    public static string GetAppSettings()
    {
        var config = new
        {
            Environment = "production",
            Version = "1.2.0",
            Features = new { DarkMode = true, BetaAccess = false },
            MaxConnections = 100
        };

        return JsonSerializer.Serialize(config, new JsonSerializerOptions { WriteIndented = true });
    }
}

using ModelContextProtocol.Server;
using System.ComponentModel;

namespace McpHttpServer;

[McpServerToolType]
public static class ServerTools
{
    [McpServerTool, Description("Returns the current server status and uptime")]
    public static string GetStatus()
    {
        return $"Server is healthy. Uptime: {Environment.TickCount64 / 1000}s";
    }

    [McpServerTool, Description("Echoes the provided message back")]
    public static string Echo([Description("The message to echo")] string message)
    {
        return $"Echo: {message}";
    }
}

